  "3.1.1.1": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation Kapitel 3 Vårdverksamhetens behov.pdf", "sida": 4}, "beskrivning": [], "maskerat": false, "sammanfattning": null},
  "3.1.1.2": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation Kapitel 3 Vårdverksamhetens behov.pdf", "sida": 4}, "beskrivning": [], "maskerat": false, "sammanfattning": null},
