  "KD1.1.1.10": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 6}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.1.10 sekretessmaskering.pdf", "sida": "1 till 4", "maskerad": true}], "maskerat": "helt", "sammanfattning": null, "motivering": 287},
