  "KD1.1.4.3": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 10}, "beskrivning": [], "maskerat": false, "sammanfattning": null},
  "KD1.1.4.4": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 11}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.4.4.pdf", "sida": "1 till 2", "maskerad": false}], "maskerat": false, "sammanfattning": "Cambio beskriver att COSMIC Enterprise och MetaVision körs på eKlient-PC med minst två kärnor, 2 GB RAM och 1280x1024, att Ward Board kräver pekskärm i 1920x1080 och att Nova-apparna körs på iPad med senaste iOS eller Windows 10-enheter. Varje release har en lista över testade plattformar.", "motivering": 295},
  "KD1.1.4.5": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 11}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.4.5.pdf", "sida": "1", "maskerad": false}], "maskerat": false, "sammanfattning": "Cambio utlovar att dagens krav i eKlient version 1.7 uppfylls och att varje release testas på senaste stabila Windows 10 i halvårskanalen, samt att livscyklerna för beroende programvara bevakas och provas tillsammans vid varje release.", "motivering": 297},
  "KD1.1.4.6": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 11}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.4.6.pdf", "sida": "1", "maskerad": false}], "maskerat": false, "sammanfattning": "Cambio beskriver att enda insticksprogram som krävs är en Java-COM-brygga för att COSMIC Enterprise ska kunna använda ActiveX- och COM-objekt, till exempel NetID. Den kräver förhöjd behörighet vid installation och behövs bara om sådan integration önskas.", "motivering": 298},
  "KD1.1.4.7": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 12}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.4.7.pdf", "sida": "1", "maskerad": false}], "maskerat": false, "sammanfattning": "Cambio utlovar att kärnsystemet inte kräver klientvirtualisering och anger installation på över 10 000 datorer hos kunder. Virtualisering stöds, verifierat med Microsoft Remote Desktop Services och Citrix XenApp, medan XenDesktop och VMware Horizon först behöver testas.", "motivering": 299},
  "KD1.1.4.8": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 12}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.4.8.pdf", "sida": "1", "maskerad": false}], "maskerat": false, "sammanfattning": "Cambio beskriver att kärnsystemet saknar egna beroenden av klientprogram, men att vissa funktioner kräver installation av NetID för smarta kort, Dragon Medical med .NET 4.5 för taligenkänning, Crystal Reports för utskrifter, Skype for Business för e-besök, Word och ett PDF-verktyg för mallar.", "motivering": 300},
  "KD1.1.4.9": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 12}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.4.9.pdf", "sida": "1 till 2", "maskerad": false}], "maskerat": false, "sammanfattning": "Cambio beskriver att klientpaket levereras i god tid och kopieras ut med skript, att tredjepartsprodukter levereras som MSI-paket, att mobilappar uppdateras via MAM/MDM och webbklienter inte kräver installation. En kompatibilitetsmatris tas fram per release, och läskopia används vid behov.", "motivering": 301},
  "KD1.1.4.10": {"svar": "ja", "kryss": {"fil": "CAMBIO Kravspecifikation drift och teknik.pdf", "sida": 13}, "beskrivning": [{"fil": "CAMBIO Anbudssvar_KAP01_1.1.4.10 sekretessmaskering.pdf", "sida": "1", "maskerad": true}], "maskerat": "helt", "sammanfattning": null, "motivering": 302},
